// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 randomSelector) public {
        // IAccessControl interface id derived from its declared selectors (not hard-coded)
        bytes4 sig1 = bytes4(keccak256("hasRole(bytes32,address)"));
        bytes4 sig2 = bytes4(keccak256("getRoleAdmin(bytes32)"));
        bytes4 sig3 = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 sig4 = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 sig5 = bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 accessControlId = sig1 ^ sig2 ^ sig3 ^ sig4 ^ sig5;
        // IERC165 interface id derived from its declared selector
        bytes4 erc165Id = bytes4(keccak256("supportsInterface(bytes4)"));

        bool recognized = c.supportsInterface(randomSelector);
        bool correctRecognition =
            (recognized == (randomSelector == accessControlId || randomSelector == erc165Id));
        // the timelock controller must always advertise IAccessControl support
        assertTrue(correctRecognition && c.supportsInterface(accessControlId));
    }
}
